import{_ as n,c as t,o as i,ah as r}from"./chunks/framework.dGCgOE9J.js";const s="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_project_list.jpg",a="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_schema_settings.jpg",l="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_pipe_branch_settings.jpg",o="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_cost_rates.jpg",d="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_cost_rate_form.jpg",h="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_geopackage_config.jpg",u="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_user_settings.jpg",w=JSON.parse('{"title":"22. Projektbezogene Konfiguration","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-b-betrieb-admin-qgis/22-projektbezogene-konfiguration.md","filePath":"manual/teil-b-betrieb-admin-qgis/22-projektbezogene-konfiguration.md"}'),g={name:"manual/teil-b-betrieb-admin-qgis/22-projektbezogene-konfiguration.md"};function c(m,e,p,b,z,k){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="_22-projektbezogene-konfiguration" tabindex="-1">22. Projektbezogene Konfiguration <a class="header-anchor" href="#_22-projektbezogene-konfiguration" aria-label="Permalink to &quot;22. Projektbezogene Konfiguration&quot;">​</a></h1><p>Drei Ansichten der Weboberfläche hängen von Einstellungen ab, die je Projekt im Administrationsbereich hinterlegt werden: das Netzschema, die Rohrverzweigung und die Wertermittlung. Dazu kommen zwei Einstellungen, die nicht an ein Projekt gebunden sind: die Zusammenstellung des GeoPackage-Schemas und die gespeicherten Einstellungen der Nutzenden.</p><p>Die drei Projekteinstellungen pflegen Sie am bequemsten im Formular des Projekts unter „Api“ → „Projekte“, wo sie unter den Feldern des Projekts stehen, siehe Abschnitt <a href="./21-projekte-und-stammdaten.html#_21-1-projekte-anlegen-und-vorbelegungen-setzen">Projekte anlegen und Vorbelegungen setzen</a>. Jede hat außerdem eine eigene Liste: „Netzwerkschema“, „Rohrverzweigung“ und „Wertermittlungssätze“.</p><p>Die Projektliste zeigt in drei Spalten, was eingerichtet ist: „Ausgeschlossene Netzknotentypen“ und „Netzknotentypen“ aus den Netzschema-Einstellungen, „Rohrverzweigungs-Typen“ aus den Rohrabzweig-Einstellungen. Die Spalte „Netzknotentypen“ meint die Typen mit der Schaltfläche „Subnetz öffnen“. „Keine“ oder „Keine konfiguriert“ heißt, die Einstellung ist angelegt, aber leer; „Nicht konfiguriert“ heißt, sie fehlt ganz. Der Unterschied ist wichtig, siehe Abschnitt <a href="#_22-2-einstellungen-der-rohrverzweigung">Einstellungen der Rohrverzweigung</a>.</p><p><img src="'+s+'" alt="Screenshot der Liste der Projekte im Administrationsbereich mit Hervorhebung der drei Spalten zu den Projekteinstellungen rechts" data-zoomable="true"></p><h2 id="_22-1-netzschema-einstellungen" tabindex="-1">22.1 Netzschema-Einstellungen <a class="header-anchor" href="#_22-1-netzschema-einstellungen" aria-label="Permalink to &quot;22.1 Netzschema-Einstellungen&quot;">​</a></h2><p>Die <strong>Netzschema-Einstellungen</strong> legen fest, welche Netzknoten das Netzschema eines Projekts zeigt, siehe Kapitel <a href="./../teil-a-anwenderhandbuch/14-netzschema.html">Netzschema</a>. Sie haben zwei Auswahlfelder:</p><ul><li>„Ausgeschlossene Netzknotentypen“ – Netzknoten dieser Typen erscheinen nicht im Schema. Üblich sind die Hausanschlüsse, deren Zahl das Schema unübersichtlich machen würde.</li><li>„Kindansicht aktivierte Netzknotentypen“ – an Netzknoten dieser Typen erscheint die Schaltfläche „Subnetz öffnen“, siehe Abschnitt <a href="./../teil-a-anwenderhandbuch/14-netzschema.html#_14-9-subnetz-eines-netzknotens">Subnetz eines Netzknotens</a>. Der Hilfetext unter dem Feld nennt die Schaltfläche „Hausanschlusskabel-Schema öffnen“; gemeint ist „Subnetz öffnen“.</li></ul><p><img src="'+a+'" alt="Screenshot der Netzschema-Einstellungen eines Projekts mit Hervorhebung der beiden Auswahlfelder untereinander" data-zoomable="true"></p><p>Markieren Sie einen Typ in der linken Liste und verschieben Sie ihn mit dem Pfeil nach rechts.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Fehlen die Netzschema-Einstellungen, meldet das Netzschema beim Öffnen „Die Netzschema-Einstellungen sind für dieses Projekt nicht konfiguriert. Bitte konfigurieren Sie diese im Admin-Bereich.“, zeigt alle Netzknoten des Projekts, und „Subnetz öffnen“ erscheint nirgends. Sind sie angelegt, aber leer, gilt dasselbe ohne die Meldung.</p></div><h2 id="_22-2-einstellungen-der-rohrverzweigung" tabindex="-1">22.2 Einstellungen der Rohrverzweigung <a class="header-anchor" href="#_22-2-einstellungen-der-rohrverzweigung" aria-label="Permalink to &quot;22.2 Einstellungen der Rohrverzweigung&quot;">​</a></h2><p>Die <strong>Rohrabzweig-Einstellungen</strong> legen fest, welche Netzknoten die Rohrverzweigung als Rohrabzweig anbietet, siehe Kapitel <a href="./../teil-a-anwenderhandbuch/12-rohrverzweigung.html">Rohrverzweigung</a>. Ihr einziges Feld ist „Erlaubte Netzknotentypen“.</p><p><img src="'+l+'" alt="Screenshot der Rohrabzweig-Einstellungen eines Projekts mit Hervorhebung des Feldes „Erlaubte Netzknotentypen“" data-zoomable="true"></p><p>Es gibt drei Zustände, und nur zwei davon sind gewollt:</p><ul><li><strong>Keine Einstellungen</strong> – die Rohrverzweigung bietet alle Netzknoten des Projekts an und weist mit „Rohrabzweig-Einstellungen für dieses Projekt nicht konfiguriert.“ darauf hin.</li><li><strong>Einstellungen mit mindestens einem Typ</strong> – angeboten werden nur Netzknoten dieser Typen.</li><li><strong>Einstellungen ohne Typ</strong> – angeboten wird kein einziger Netzknoten, ohne Hinweis.</li></ul><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Wer die Einstellungen anlegt und das Feld leer lässt, sperrt die Rohrverzweigung für das Projekt, und die Weboberfläche sagt nicht warum. Wählen Sie mindestens einen Typ aus, oder löschen Sie die Einstellungen wieder.</p><p>Eine neue Installation steht für das Projekt „Default“ genau in diesem Zustand: Sie bringt leere Rohrabzweig- und Netzschema-Einstellungen mit. Wählen Sie dort Typen aus, bevor das Projekt genutzt wird.</p></div><h2 id="_22-3-kostensatze-der-wertermittlung" tabindex="-1">22.3 Kostensätze der Wertermittlung <a class="header-anchor" href="#_22-3-kostensatze-der-wertermittlung" aria-label="Permalink to &quot;22.3 Kostensätze der Wertermittlung&quot;">​</a></h2><p>Die Wertermittlung rechnet mit den Kostensätzen des Projekts; was sie daraus macht, beschreibt Abschnitt <a href="./../teil-a-anwenderhandbuch/09-wertermittlung.html#_9-3-woher-die-kostensatze-kommen">Woher die Kostensätze kommen</a>. Sie stehen unter „Wertermittlungssätze“, eine Zeile je Kostenbereich. Eine neue Installation bringt keine mit; ohne sie lässt sich die Wertermittlung nicht benutzen.</p><p><img src="'+o+'" alt="Screenshot der Wertermittlungssätze, gefiltert auf ein Projekt, mit Kostenbereich, Betrag, Einheit und Hausanschluss-Kennzeichnung" data-zoomable="true"></p><p>Ein Kostensatz hat diese Felder:</p><ul><li>„Kostenkategorie“ – der Name, der in der Wertermittlung als Kostenbereich erscheint. Er ist je Projekt eindeutig.</li><li>„Betrag“ – in Euro, netto oder brutto nach Ihrer Festlegung; Qonnectra rechnet ihn nicht um.</li><li>„Einheit“ – „pro Meter“ oder „Stück“.</li><li>„Hausanschluss“ – zählt die Netzknoten dieses Satzes für die Kennzahl „Kosten pro Hausanschluss“.</li><li>„Netzknotentypen“ – bei „Stück“ die Typen, deren Netzknoten gezählt werden.</li></ul><p><img src="'+d+'" alt="Screenshot des Formulars eines Kostensatzes mit Hervorhebung von Einheit, Hausanschluss und Netzknotentypen" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Wählen Sie bei „Stück“ mindestens einen Netzknotentyp aus. Ohne ihn geht der Satz ohne Hinweis mit 0 € ein, siehe Abschnitt <a href="./../teil-a-anwenderhandbuch/09-wertermittlung.html#_9-3-woher-die-kostensatze-kommen">Woher die Kostensätze kommen</a>.</p></div><p>Ein Netzknotentyp gehört sinnvollerweise zu genau einem Kostensatz. Steht er in zweien, zählt jeder seiner Netzknoten doppelt.</p><h2 id="_22-4-geopackage-schema-konfigurieren" tabindex="-1">22.4 GeoPackage-Schema konfigurieren <a class="header-anchor" href="#_22-4-geopackage-schema-konfigurieren" aria-label="Permalink to &quot;22.4 GeoPackage-Schema konfigurieren&quot;">​</a></h2><p>Ein <strong>GeoPackage-Schema</strong> ist eine leere GeoPackage-Datei mit dem Aufbau der Qonnectra-Tabellen. Sie dient als Vorlage für Daten, die außerhalb erfasst und später übernommen werden, siehe Abschnitt <a href="./24-daten-import-und-export.html#_24-2-geopackage-schema-herunterladen">GeoPackage-Schema herunterladen</a>. Welche Tabellen sie enthält, legt eine <strong>Konfiguration</strong> fest. Sie steht unter „GeoPackage-Schema-Konfigurationen“ und gilt für die ganze Installation.</p><p><img src="'+h+'" alt="Screenshot einer GeoPackage-Schema-Konfiguration mit Hervorhebung der Auswahl der Layer" data-zoomable="true"></p><p>Eine Konfiguration hat einen Namen und unter „Ausgewählte Layer“ die Liste der Tabellen. Zur Auswahl stehen:</p><ul><li>die vier Layer mit Geometrie – „trench“, „node“, „address“ und „area“ –, in der Liste mit dem Geometrietyp in Klammern,</li><li>die Fachtabellen ohne Geometrie – „conduit“, „microduct“, „cable“ –,</li><li>die Stammdaten, deren Werte in den Layern als Nummern stehen, etwa „attributes_status“ oder „attributes_node_type“, sowie „projects“ und „flags“.</li></ul><p>Legen Sie mehrere Konfigurationen an, wenn verschiedene Aufgaben verschiedene Tabellen brauchen, etwa eine für die Feldaufnahme von Adressen und eine für Trassen.</p><h2 id="_22-5-benutzereinstellungen-zurucksetzen" tabindex="-1">22.5 Benutzereinstellungen zurücksetzen <a class="header-anchor" href="#_22-5-benutzereinstellungen-zurucksetzen" aria-label="Permalink to &quot;22.5 Benutzereinstellungen zurücksetzen&quot;">​</a></h2><p>Unter „Benutzereinstellungen“ steht für jedes Konto, das seine Einstellungen einmal mit „In Konto speichern“ abgelegt hat, eine Zeile mit diesem Speicherstand, siehe Abschnitt <a href="./../teil-a-anwenderhandbuch/17-einstellungen.html#_17-2-einstellungen-im-konto-speichern-und-wieder-laden">Einstellungen im Konto speichern und wieder laden</a>.</p><p><img src="'+u+'" alt="Screenshot der Liste der Benutzereinstellungen mit dem Speicherstand eines Kontos oben im Inhaltsbereich" data-zoomable="true"></p><p>Löschen Sie eine Zeile, ist der Speicherstand des Kontos entfernt. Das ist der Weg, wenn ein gespeicherter Stand Fehler verursacht, etwa weil er nach einer Aktualisierung von Qonnectra Einstellungen enthält, mit denen die Anwendung nicht mehr zurechtkommt.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Das Löschen setzt nichts zurück, was die Person gerade sieht. Ihre Einstellungen liegen im Browser, und dort bleiben sie. „Aus Konto laden“ findet danach nichts, ändert nichts und meldet das nicht. Damit die Ausgangswerte wieder gelten, setzt die Person sie in „Einstellungen“ selbst zurück oder löscht die Browserdaten der Anwendung.</p></div>',36)])])}const _=n(g,[["render",c]]);export{w as __pageData,_ as default};
